 String source()throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/NativeRewardsEntryHelper.java"));}
 @Test public void exactMode(){String[] a=new String[11];a[10]="SHOW_REGION_V52";assertTrue(NativeRewardsEntryHelper.validModeArguments(a));a[10]="SHOW_REGION_V52 ";assertFalse(NativeRewardsEntryHelper.validModeArguments(a));assertTrue(NativeRewardsEntryHelper.validModeArguments(new String[10]));}
 @Test public void exactResources(){String[] ids={"homePageWrapper","dailyTaskPanel","dailyActivities","search","read"};for(int i=0;i<5;i++){assertEquals(i,NativeRewardsEntryHelper.regionResource(ids[i]));assertEquals(-1,NativeRewardsEntryHelper.regionResource(ids[i]+" "));assertEquals(-1,NativeRewardsEntryHelper.regionResource("com.microsoft.bing:id/"+ids[i]));}assertEquals(-1,NativeRewardsEntryHelper.regionResource(null));}
 @Test public void uniqueCompleteChainOnly(){assertTrue(NativeRewardsEntryHelper.uniqueRegionCounts(new int[]{1,1,1,1,1}));for(int i=0;i<5;i++){int[] a={1,1,1,1,1};a[i]=0;assertFalse(NativeRewardsEntryHelper.uniqueRegionCounts(a));a[i]=2;assertFalse(NativeRewardsEntryHelper.uniqueRegionCounts(a));}assertFalse(NativeRewardsEntryHelper.uniqueRegionCounts(null));assertFalse(NativeRewardsEntryHelper.uniqueRegionCounts(new int[4]));}
