 @Test public void noTruncatedOrVisibleOnlyMatching()throws Exception{String s=source();String body=s.substring(s.indexOf("private static Tree walkRegion("),s.indexOf("private static Tree walk(UiAutomation ui,NativeRewardsEntryProtocol.Binding b,Cleanup clean,boolean"));assertTrue(body.contains("while(!queue.isEmpty())"));assertTrue(body.contains("counts[resource]++"));assertTrue(body.contains("uniqueRegionCounts(counts)"));assertTrue(body.contains("scheduled+count>512"));assertTrue(body.contains("item.depth()>=32"));assertTrue(body.contains("chars+length>32768"));assertTrue(body.contains("n.isVisibleToUser()&&resource!=4"));assertTrue(body.contains("root.isVisibleToUser()"));assertTrue(body.contains("verifyActiveWindow(root,window,clean)"));}
